import{_ as a,o as t,c as i,ai as r}from"./chunks/framework.Cabe_Szf.js";const m=JSON.parse(`{"title":"Radiographie de l'invite","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://lognebudo.github.io/llmxray/docs/fr/guide/xray.html"}]]},"headers":[],"relativePath":"fr/guide/xray.md","filePath":"fr/guide/xray.md","lastUpdated":1792397420000}`),s={name:"fr/guide/xray.md"};function o(n,e,l,u,d,p){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="radiographie-de-l-invite" tabindex="-1">Radiographie de l&#39;invite <a class="header-anchor" href="#radiographie-de-l-invite" aria-label="Permalink to &quot;Radiographie de l&#39;invite&quot;">​</a></h1><p>La <strong>Radiographie de l&#39;invite</strong> dessine l&#39;invite de chaque tour à l&#39;échelle et dit, partie par partie, ce qu&#39;elle était et ce qui lui est arrivé : déjà dans la mémoire du modèle, relue, ou coupée par le démon et jamais vue.</p><p><strong>Élément de la barre latérale :</strong> Radiographie de l&#39;invite (sous Exécutions) <strong>Route :</strong> <code>/xray</code><strong>Ajouté dans :</strong> v0.8.0 (octobre 2026) <strong>Nécessite :</strong> des tours sur la page En direct. La radiographie lit ce que le port d&#39;observation a enregistré ; pointez un outil vers <code>http://localhost:11435</code> et envoyez quelques messages.</p><h2 id="a-quoi-ca-sert" tabindex="-1">À quoi ça sert ? <a class="header-anchor" href="#a-quoi-ca-sert" aria-label="Permalink to &quot;À quoi ça sert ?&quot;">​</a></h2><p>Trois choses tournent mal avec une invite sur un modèle local, et aucune n&#39;est visible depuis l&#39;outil qui l&#39;a envoyée.</p><ul><li>L&#39;invite cesse de correspondre au tour précédent quelque part vers le début, si bien que le modèle relit tout ce qui suit. Un horodatage dans l&#39;invite système fait cela à chaque tour.</li><li>Des schémas d&#39;outils sont activés et prennent dès lors une part fixe de chaque invite.</li><li>L&#39;invite dépasse le contexte : Ollama garde les premiers tokens et la fin, supprime le milieu, et répond comme si de rien n&#39;était. L&#39;invite système fait généralement partie de ce qui a été supprimé.</li></ul><p>La radiographie montre les trois sous forme d&#39;image de l&#39;invite elle-même.</p><h2 id="lire-le-graphique" tabindex="-1">Lire le graphique <a class="header-anchor" href="#lire-le-graphique" aria-label="Permalink to &quot;Lire le graphique&quot;">​</a></h2><p>Une barre par tour, de gauche à droite en tokens tels que le démon les a comptés. L&#39;invite la plus large de la conversation fixe l&#39;échelle.</p><p><strong>La couleur dit ce qu&#39;est la partie :</strong> invite système, schémas d&#39;outils, tours précédents, nouveau message, dans l&#39;ordre où le démon les lit.</p><p><strong>La luminosité dit ce qui lui est arrivé :</strong></p><ul><li><strong>Atténuée</strong> : déjà dans la mémoire du modèle depuis le tour précédent. N&#39;a rien coûté.</li><li><strong>Vive</strong> : relue à ce tour.</li><li><strong>Hachurée et barrée</strong> : coupée par le démon. Le modèle ne l&#39;a jamais vue.</li></ul><p>Un mince espace sépare les parties, pour qu&#39;une barre se lise d&#39;un coup d&#39;œil comme une structure. La colonne de droite donne le temps de lecture de l&#39;invite et la part qui était en mémoire.</p><p>Sous une barre, une note n&#39;apparaît que lorsqu&#39;il s&#39;est passé quelque chose :</p><ul><li>le premier tour de cet outil avec ce modèle ;</li><li>le modèle a été rechargé, donc rien n&#39;était en mémoire et l&#39;invite n&#39;y est pour rien ;</li><li>l&#39;invite a cessé de correspondre au tour précédent, avec la partie concernée et la position en tokens, qui est une estimation à partir des caractères ;</li><li>des outils ont été activés, avec le nombre de tokens de schémas qui figurent désormais dans chaque invite ;</li><li>l&#39;invite a dépassé le contexte, avec le nombre de tokens supprimés et si l&#39;invite système et les schémas d&#39;outils en faisaient partie.</li></ul><h2 id="cliquer-sur-une-partie" tabindex="-1">Cliquer sur une partie <a class="header-anchor" href="#cliquer-sur-une-partie" aria-label="Permalink to &quot;Cliquer sur une partie&quot;">​</a></h2><p>Cliquez sur n&#39;importe quel segment et la requête de ce tour s&#39;ouvre en dessous, dans le même visualiseur de requêtes que la page En direct, en commençant par la partie cliquée. Le visualiseur marque, dans le texte même, l&#39;endroit où l&#39;invite a cessé de correspondre à la précédente.</p><p>Le texte de la requête n&#39;est conservé que si <strong>Conserver le texte de l&#39;invite</strong> est activé sur la page En direct. Sans cela, les tailles sont exactes mais le texte n&#39;est pas disponible ; la page le dit.</p><p>Depuis une requête, <strong>Voir cet appel dans son exécution</strong> ouvre la page <a href="./runs.html">Exécutions</a> sur ce même appel.</p><h2 id="les-totaux" tabindex="-1">Les totaux <a class="header-anchor" href="#les-totaux" aria-label="Permalink to &quot;Les totaux&quot;">​</a></h2><p>Sous le graphique, une phrase : combien de temps la lecture de l&#39;invite a pris sur la conversation, combien une invite stable en aurait évité, et combien de tours ont répondu à une invite qui n&#39;a pas été envoyée en entier.</p><p>L&#39;économie est une estimation. Elle suppose que le temps de lecture de l&#39;invite croît avec le nombre de tokens hors du cache, ce qui est vrai en bonne approximation.</p><h2 id="ce-que-la-page-ne-sait-pas" tabindex="-1">Ce que la page ne sait pas <a class="header-anchor" href="#ce-que-la-page-ne-sait-pas" aria-label="Permalink to &quot;Ce que la page ne sait pas&quot;">​</a></h2><p>Le découpage en tokens propre au modèle. Les largeurs sont les comptes de tokens du démon ; quand une barre est découpée en parties, le découpage est proportionnel aux caractères. La partie hachurée est dimensionnée d&#39;après l&#39;écart entre ce qui a été envoyé et ce que le démon a compté. Chaque estimation de la page est indiquée comme telle.</p><h2 id="voir-aussi" tabindex="-1">Voir aussi <a class="header-anchor" href="#voir-aussi" aria-label="Permalink to &quot;Voir aussi&quot;">​</a></h2><ul><li><a href="./live.html">En direct</a> enregistre les tours que la radiographie dessine.</li><li><a href="./runs.html">Exécutions</a> pose les appels d&#39;un outil dans le temps, avec ce que chacun a envoyé et reçu.</li><li><a href="./cache-lab.html">Labo de cache</a> mesure, sur votre propre démon, ce que rapporte la correction d&#39;une rupture de cache.</li><li><a href="./shared-box.html">Machine partagée</a> montre ce que les réglages de chaque outil coûtent aux autres.</li></ul>',26)])])}const h=a(s,[["render",o]]);export{m as __pageData,h as default};
